 * Cell addresses. A column is one or two letters (A..Z, then AA..ZZ) and a row
 * is one to three digits naming a row of at least 1.
 */

const ADDRESS = /^([A-Za-z]{1,2})([0-9]{1,3})$/

export const MAX_COLUMN = 26 * 26 + 26 // ZZ
export const MAX_ROW = 999

/** The number a column name denotes: A is 1, Z is 26, AA is 27, ZZ is 702. */
export function columnNumber(letters) {
  let n = 0
  for (const ch of letters.toUpperCase()) n = n * 26 + (ch.charCodeAt(0) - 64)
  return n
}

/** The name of a column number. */
export function columnName(n) {
  let name = ''
  let rest = n
  while (rest > 0) {
    const rem = (rest - 1) % 26
    name = String.fromCharCode(65 + rem) + name
    rest = (rest - 1 - rem) / 26
  }
  return name
}

/**
 * Reads a word as an address inside the addressable range, or returns null when
 * it names no such cell.
 */
export function parseAddress(word) {
  const m = ADDRESS.exec(word)
  if (!m) return null
  const col = columnNumber(m[1])
  const row = Number(m[2])
  if (col < 1 || col > MAX_COLUMN) return null
  if (row < 1 || row > MAX_ROW) return null
  return { col, row }
}

/** The canonical, upper-cased text of an address. */
export function addressText(col, row) {
  return columnName(col) + String(row)
}

export function addressKey(col, row) {
  return addressText(col, row)
}

/** Orders addresses by column and then by row. */
export function compareAddresses(a, b) {
  return a.col - b.col || a.row - b.row
}
"}

