chunk.argumentsDelta:
{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e5-handoff-tax-t5/cell-srM07v/src/sheet.js","content":"/**
 * Reading a sheet: one cell to a line, an address and then the content.
 */

import { parseAddress, addressKey, compareAddresses } from './address.js'

export class SheetError extends Error {}

/**
 * Splits the input into lines, dropping the empty tail a trailing newline
 * leaves.
 */
function lines(input) {
  const parts = input.split('\n')
  if (parts.length > 0 && parts[parts.length - 1] === '') parts.pop()
  return parts
}

function isBlank(ch) {
  return ch === ' ' || ch === '\t'
}

/**
 * Reads the sheet, throwing a SheetError with the message for the first line
 * that names no cell or names one already declared.
 */
export function parseSheet(input) {
  const cells = new Map()
  const all = lines(input)
  for (let i = 0; i < all.length; i++) {
    const line = all[i]
    const lineNumber = i + 1
    let at = 0
    while (at < line.length && isBlank(line[at])) at++
    if (at >= line.length) continue
    if (line[at] === '#') continue
    const start = at
    while (at < line.length && !isBlank(line[at])) at++
    const word = line.slice(start, at)
    if (at < line.length) {
      while (at < line.length && isBlank(line[at])) at++
    }
    const content = line.slice(at)
    const address = parseAddress(word)
    if (address === null) {
      throw new SheetError(`error: line ${lineNumber}: invalid cell address ${word}`)
    }
    const key = addressKey(address.col, address.row)
    if (cells.has(key)) {
      throw new SheetError(`error: line ${lineNumber}: cell ${key} is declared twice`)
    }
    cells.set(key, { col: address.col, row: address.row, key, content })
  }
  return [...cells.values()].sort(compareAddresses)
}
"}

