{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e5-handoff-tax-t5/cell-srM07v/src/formula.js","content":"/**
 * The formula grammar: numbers, cell addresses, ranges, TRUE and FALSE, calls,
 * parentheses and the operators.
 */

import { parseAddress } from './address.js'

const NUMBER = /^[0-9]+(\.[0-9]+)?/
const WORD = /^[A-Za-z][A-Za-z0-9]*/

const OPERATORS = ['<>', '<=', '>=', '^', '*', '/', '+', '-', '=', '<', '>']

/** Splits a formula body into tokens, or returns null when a character fits none. */
function tokenize(body) {
  const tokens = []
  let at = 0
  while (at < body.length) {
    const ch = body[at]
    if (ch === ' ' || ch === '\t') {
      at++
      continue
    }
    if (ch >= '0' && ch <= '9') {
      const m = NUMBER.exec(body.slice(at))
      tokens.push({ kind: 'number', text: m[0] })
      at += m[0].length
      continue
    }
    const word = WORD.exec(body.slice(at))
    if (word) {
      tokens.push({ kind: 'word', text: word[0] })
      at += word[0].length
      continue
    }
    if (ch === '(' || ch === ')' || ch === ',' || ch === ':') {
      tokens.push({ kind: ch, text: ch })
      at++
      continue
    }
    const op = OPERATORS.find((candidate) => body.startsWith(candidate, at))
    if (op) {
      tokens.push({ kind: 'op', text: op })
      at += op.length
      continue
    }
    return null
  }
  return tokens
}

class Failure extends Error {}

class Parser {
  constructor(tokens) {
    this.tokens = tokens
    this.at = 0
  }

  peek() {
    return this.at < this.tokens.length ? this.tokens[this.at] : null
  }

  next() {
    const token = this.peek()
    if (token === null) throw new Failure('end of input')
    this.at++
    return token
  }

  atOp(...ops) {
    const token = this.peek()
    return token !== null && token.kind === 'op' && ops.includes(token.text)
  }

  expect(kind) {
    const token = this.next()
    if (token.kind !== kind) throw new Failure('unexpected token')
    return token
  }

  parseExpression() {
    return this.parseComparison()
  }

  parseComparison() {
    let left = this.parseAdditive()
    while (this.atOp('=', '<>', '<', '<=', '>', '>=')) {
      const op = this.next().text
      const right = this.parseAdditive()
      left = { t: 'bin', op, l: left, r: right }
    }
    return left
  }

  parseAdditive() {
    let left = this.parseMultiplicative()
    while (this.atOp('+', '-')) {
      const op = this.next().text
      const right = this.parseMultiplicative()
      left = { t: 'bin', op, l: left, r: right }
    }
    return left
  }

  parseMultiplicative() {
    let left = this.parsePower()
    while (this.atOp('*', '/')) {
      const op = this.next().text
      const right = this.parsePower()
      left = { t: 'bin', op, l: left, r: right }
    }
    return left
  }

  // `^` groups to the right, and a leading sign binds tighter than it.
  parsePower() {
    const base = this.parseUnary()
    if (this.atOp('^')) {
      this.next()
      const exponent = this.parsePower()
      return { t: 'bin', op: '^', l: base, r: exponent }
    }
    return base
  }

  parseUnary() {
    if (this.atOp('-', '+')) {
      const op = this.next().text
      return { t: 'un', op, x: this.parseUnary() }
    }
    return this.parsePrimary()
  }

  parsePrimary() {
    const token = this.next()
    if (token.kind === 'number') return { t: 'num', v: Number(token.text) }
    if (token.kind === '(') {
      const inner = this.parseExpression()
      this.expect(')')
      return inner
    }
    if (token.kind === 'word') {
      const ahead = this.peek()
      if (ahead !== null && ahead.kind === '(') {
        this.next()
        const args = []
        if (this.peek() !== null && this.peek().kind === ')') {
          this.next()
        } else {
          for (;;) {
            args.push(this.parseExpression())
            const sep = this.next()
            if (sep.kind === ')') break
            if (sep.kind !== ',') throw new Failure('unexpected token')
          }
        }
        return { t: 'call', name: token.text.toUpperCase(), args }
      }
      const first = this.word(token.text)
      if (first.t === 'ref' && ahead !== null && ahead.kind === ':') {
        this.next()
        const end = this.expect('word')
        const second = this.word(end.text)
        if (second.t !== 'ref') throw new Failure('unexpected token')
        return { t: 'range', a: first, b: second }
      }
      return first
    }
    throw new Failure('unexpected token')
  }

  /** A word that names no call is TRUE, FALSE, or a cell address. */
  word(text) {
    const upper = text.toUpperCase()
    if (upper === 'TRUE') return { t: 'bool', v: true }
    if (upper === 'FALSE') return { t: 'bool', v: false }
    const address = parseAddress(text)
    if (address === null) return { t: 'ref', valid: false, text: upper }
    return { t: 'ref', valid: true, col: address.col, row: address.row }
  }
}

/**
 * Marks the ranges that sit directly under a call, the only place a range may
 * appear. Returns false when one sits anywhere else.
 */
function checkRanges(node, allowRange) {
  if (node.t === 'range') return allowRange
  if (node.t === 'call') return node.args.every((arg) => checkRanges(arg, true))
  if (node.t === 'bin') return checkRanges(node.l, false) && checkRanges(node.r, false)
  if (node.t === 'un') return checkRanges(node.x, false)
  return true
}

/**
 * Parses a formula body. Returns { ok: false } when the grammar rejects it, and
 * otherwise the tree together with whether a range sits where it may not.
 */
export function parseFormula(body) {
  const tokens = tokenize(body)
  if (tokens === null) return { ok: false }
  const parser = new Parser(tokens)
  let node
  try {
    node = parser.parseExpression()
  } catch (error) {
    if (error instanceof Failure) return { ok: false }
    throw error
  }
  if (parser.at !== tokens.length) return { ok: false }
  return { ok: true, node, misplacedRange: !checkRanges(node, false) }
}
"}

