 * Values: a number, text, a boolean, or an error.
 */

export const ERROR_TOKENS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']

export const num = (n) => ({ kind: 'num', n })
export const text = (s) => ({ kind: 'text', s })
export const bool = (b) => ({ kind: 'bool', b })
export const err = (token) => ({ kind: 'err', token })

export const DIV0 = err('#DIV/0!')
export const REF = err('#REF!')
export const VALUE = err('#VALUE!')
export const CYCLE = err('#CYCLE!')
export const NAME = err('#NAME?')
export const ERR = err('#ERR!')

export const isError = (value) => value.kind === 'err'

/** A number is a value only while it stays finite. */
export function finite(n) {
  return Number.isFinite(n) ? num(n) : DIV0
}

/** Reads a value in an arithmetic position. */
export function asNumber(value) {
  if (value.kind === 'err') return value
  if (value.kind === 'num') return value
  if (value.kind === 'bool') return num(value.b ? 1 : 0)
  return VALUE
}

/** Reads a literal: empty is zero, then numbers, then error tokens, then text. */
export function readLiteral(content) {
  if (content === '') return num(0)
  if (/^-?[0-9]+(\.[0-9]+)?$/.test(content)) return num(Number(content))
  if (ERROR_TOKENS.includes(content)) return err(content)
  return text(content)
}

/** A number prints as JavaScript would after rounding to ten significant digits. */
export function formatNumber(n) {
  const rounded = Number(n.toPrecision(10))
  return String(rounded === 0 ? 0 : rounded)
}

