/**
 * The command. `node src/cli.js values` prints the value of every cell in the
 * sheet read from standard input, and `node src/cli.js deps` prints the cells
 * each one reads.
 */

import { readFileSync } from 'node:fs'
import { parseSheet, SheetError } from './sheet.js'
import { Evaluator } from './evaluate.js'
import { dependencies } from './deps.js'
import { formatValue } from './value.js'

function fail(message) {
  process.stderr.write(`${message}\n`)
  process.exit(2)
}

function readStdin() {
  try {
    return readFileSync(0, 'utf8')
  } catch {
    return ''
  }
}

function main(argv) {
  const mode = argv.length === 1 ? argv[0] : null
  if (mode !== 'values' && mode !== 'deps') fail('error: usage: cli.js values|deps')

  let cells
  try {
    cells = parseSheet(readStdin())
  } catch (error) {
    if (error instanceof SheetError) fail(error.message)
    throw error
  }

  const out = []
  if (mode === 'values') {
    const evaluator = new Evaluator(new Map(cells.map((cell) => [cell.key, cell])))
    for (const cell of cells) {
      out.push(`${cell.key}=${formatValue(evaluator.cellValue(cell.col, cell.row))}\n`)
    }
  } else {
    for (const cell of cells) {
      const names = dependencies(cell.content)
      out.push(`${cell.key}:${names.map((name) => ` ${name}`).join('')}\n`)
    }
  }
  process.stdout.write(out.join(''))
}

main(process.argv.slice(2))
